solution:
use xiom.io;
use xiom.convert;
fn item_total(price: Float64, qty: Int) -> Float64 {
  return price * (qty as Float64);
}

fn apply_discount(total: Float64, pct: Float64) -> Float64 {
  return total - (total * pct / 100.0);
}

fn format_price(amount: Float64) -> Str {
  return "$" + convert.float_to_string(amount);
}

fn main() {
  let price = 15.0;
  let qty = 3;
  let total = item_total(price, qty);
  let discounted = apply_discount(total, 15.0);
  io.println("Shopping cart total computed!");
}
